import requests
from bs4 import BeautifulSoup
import re

# Fetch and parse all papers' tables and key info
papers = {
    'KOR-Bench': '2410.06526v3',
    'ZebraLogic': '2502.01100v2',
    'BBEH': '2502.19187v1',
    'K&K': '2410.23123v1',
}

for name, vid in papers.items():
    url = f'https://arxiv.org/html/{vid}'
    try:
        r = requests.get(url, timeout=15)
        soup = BeautifulSoup(r.text, 'html.parser')

        print(f"\n=== {name} ({vid}) ===")

        # Find all tables
        tables = soup.find_all('table')
        for i, table in enumerate(tables):
            rows = table.find_all('tr')
            if len(rows) > 1:
                print(f"\n  Table {i}:")
                for j, row in enumerate(rows):
                    cells = [td.get_text().strip() for td in row.find_all(['td','th'])]
                    row_str = ' | '.join(cells)
                    # Only print short rows that might have task info
                    if len(row_str) < 300 and any(re.search(r'\d+.*task|task.*\d+|\d+.*person|person.*\d+|\d+.*train|train.*\d+', row_str, re.IGNORECASE) for _ in [1]):
                        print(f"    {row_str}")
                    elif j == 0:
                        print(f"    {row_str}")

        # Also search for total task counts
        text = soup.get_text(separator='\n')
        for line in text.split('\n'):
            line = line.strip()
            if len(line) < 200 and ('total' in line.lower() or 'consists' in line.lower() or 'comprises' in line.lower()):
                if re.search(r'\d+.*task|task.*\d+', line, re.IGNORECASE):
                    print(f"  COUNT: {line}")
    except Exception as e:
        print(f"{name}: Error - {e}")
